-- Notables da árvore de passivas (card #6) para o catálogo 0.5 publicado pela V5.
--
-- Fonte: export oficial da GGG, grindinggear/poe2-skilltree-export (data.json, último push em
-- 2026-09-04, patch 0.5.5), baixado em 2026-11-21. Gerado com a mesma regra do
-- GgSkillTreeExportAdapter: só nós com isNotable da árvore principal (sem ascendência), nome
-- único por caixa, descrição = stats com a marcação [id|texto] trocada pelo texto do jogo.
--
-- Por que migration e não o import: a versão 0.5 já nasce publicada (V5), e o import só grava em
-- rascunho (ImportPassiveTreeUseCase). Patches futuros usam o import num rascunho, pela
-- administração (#17/#18). Se não houver 0.5 publicada (V5 pulada), nada é gravado.

INSERT INTO passive_notable (catalog_version_id, name, description)
SELECT v.id, n.name, n.description
FROM (SELECT id FROM catalog_version WHERE patch = '0.5' AND status = 'PUBLISHED') v
